// DunaStudio — scripts do site
// Parte gerada por build.js. Não edite à mão: altere a pasta site/ e gere de novo.
export default {"js/admin.js":{"body":"let selectedVideoFile = null;\nlet selectedPosterFile = null;\nlet pollTimer = null;\nlet clients = [];\nlet activeAlbumIdForUpload = null;\n\nfunction showToast(msg) {\n  const toast = document.getElementById('toast');\n  toast.textContent = msg;\n  toast.classList.add('show');\n  setTimeout(() => toast.classList.remove('show'), 3000);\n}\n\nfunction ownerOptionsHTML() {\n  return `<option value=\"\">Público — aparece no portfólio pra qualquer visitante</option>` +\n    clients.map(c => `<option value=\"${c.id}\">${c.email}</option>`).join('');\n}\n\nasync function loadClientsForDropdowns() {\n  const res = await fetch('api/auth/users');\n  if (!res.ok) return;\n  const users = await res.json();\n  clients = users.filter(u => !u.is_admin);\n  document.getElementById('videoOwner').innerHTML = ownerOptionsHTML();\n  document.getElementById('albumOwner').innerHTML = ownerOptionsHTML();\n  const contractOwnerSelect = document.getElementById('contractOwner');\n  if (contractOwnerSelect) {\n    contractOwnerSelect.innerHTML = `<option value=\"\">Selecione um cliente</option>` +\n      clients.map(c => `<option value=\"${c.id}\">${c.email}</option>`).join('');\n  }\n}\n\nfunction ownerLabel(ownerId) {\n  if (!ownerId) return '🌐 Público';\n  const c = clients.find(x => x.id === ownerId);\n  return c ? `🔒 ${c.email}` : '🔒 Privado';\n}\n\n// ---------- Upload de vídeo ----------\nfunction setupDropZone(dropEl, inputEl, onFile) {\n  dropEl.addEventListener('click', () => inputEl.click());\n  inputEl.addEventListener('change', () => { if (inputEl.files[0]) onFile(inputEl.files[0]); });\n  ['dragover', 'dragenter'].forEach(evt =>\n    dropEl.addEventListener(evt, (e) => { e.preventDefault(); dropEl.classList.add('has-file'); })\n  );\n  dropEl.addEventListener('dragleave', () => { if (!dropEl.dataset.filled) dropEl.classList.remove('has-file'); });\n  dropEl.addEventListener('drop', (e) => {\n    e.preventDefault();\n    const file = e.dataTransfer.files[0];\n    if (file) onFile(file);\n  });\n}\n\nsetupDropZone(document.getElementById('videoDrop'), document.getElementById('videoInput'), (file) => {\n  selectedVideoFile = file;\n  const elx = document.getElementById('videoDrop');\n  elx.textContent = `🎬 ${file.name} (${(file.size / (1024 ** 3)).toFixed(2)} GB)`;\n  elx.classList.add('has-file'); elx.dataset.filled = '1';\n});\nsetupDropZone(document.getElementById('posterDrop'), document.getElementById('posterInput'), (file) => {\n  selectedPosterFile = file;\n  const elx = document.getElementById('posterDrop');\n  elx.textContent = `🖼️ ${file.name}`;\n  elx.classList.add('has-file'); elx.dataset.filled = '1';\n});\n\n// ---------- Envio do filme: direto para o R2, em partes de 50 MB ----------\nconst PART_SIZE = window.STUDIO_PART_SIZE || 50 * 1024 * 1024;\n\nasync function apiJson(url, options = {}) {\n  const res = await fetch(url, options);\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new Error(data.error || `Erro ${res.status}`);\n  return data;\n}\n\n// Lê duração e tamanho do filme no próprio navegador (sem enviar nada)\nfunction readVideoInfo(file) {\n  return new Promise((resolve) => {\n    const video = document.createElement('video');\n    video.preload = 'metadata';\n    video.muted = true;\n    video.playsInline = true;\n    const url = URL.createObjectURL(file);\n    const done = (info) => { resolve({ ...info, video, url }); };\n    const timer = setTimeout(() => done({ duration: 0, width: 0, height: 0 }), 15000);\n    video.onloadedmetadata = () => { clearTimeout(timer); done({ duration: video.duration || 0, width: video.videoWidth, height: video.videoHeight }); };\n    video.onerror = () => { clearTimeout(timer); done({ duration: 0, width: 0, height: 0 }); };\n    video.src = url;\n  });\n}\n\n// Tira um quadro do filme para usar como capa quando nenhuma imagem é enviada\nfunction grabFrame(info) {\n  return new Promise((resolve) => {\n    const { video } = info;\n    if (!info.width) return resolve(null);\n    const timer = setTimeout(() => resolve(null), 10000);\n    video.onseeked = () => {\n      clearTimeout(timer);\n      const scale = Math.min(1, 1600 / Math.max(info.width, info.height));\n      const canvas = document.createElement('canvas');\n      canvas.width = Math.round(info.width * scale);\n      canvas.height = Math.round(info.height * scale);\n      try {\n        canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);\n        canvas.toBlob((blob) => resolve(blob), 'image/jpeg', 0.85);\n      } catch { resolve(null); }\n    };\n    video.currentTime = Math.min(30, (info.duration || 10) * 0.2);\n  });\n}\n\nfunction formatBytes(bytes) {\n  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(2)} GB` : `${Math.round(bytes / 1024 ** 2)} MB`;\n}\n\nlet uploadInProgress = false;\nwindow.addEventListener('beforeunload', (e) => {\n  if (uploadInProgress) { e.preventDefault(); e.returnValue = ''; }\n});\n\ndocument.getElementById('uploadForm').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  if (!selectedVideoFile) { showToast('Selecione o arquivo do filme'); return; }\n  const file = selectedVideoFile;\n  const submitBtn = document.getElementById('submitBtn');\n  const progress = document.getElementById('uploadProgress');\n  const setProgress = (msg) => { progress.style.display = 'block'; progress.textContent = msg; };\n  submitBtn.disabled = true;\n  submitBtn.textContent = 'Enviando...';\n  uploadInProgress = true;\n\n  let videoId = null, uploadId = null;\n  try {\n    setProgress('Lendo o filme...');\n    const info = await readVideoInfo(file);\n\n    const created = await apiJson('api/videos', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        title: document.getElementById('title').value,\n        category: document.getElementById('category').value,\n        description: document.getElementById('description').value,\n        ownerUserId: document.getElementById('videoOwner').value,\n        filename: file.name\n      })\n    });\n    videoId = created.id;\n    loadVideos();\n\n    const poster = selectedPosterFile || await grabFrame(info);\n    URL.revokeObjectURL(info.url);\n    if (poster) {\n      setProgress('Enviando a capa...');\n      await apiJson(`api/videos/${videoId}/poster`, { method: 'PUT', headers: { 'Content-Type': poster.type || 'image/jpeg' }, body: poster });\n    }\n\n    ({ uploadId } = await apiJson(`api/videos/${videoId}/upload/start`, {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ contentType: file.type || 'video/mp4' })\n    }));\n\n    const totalParts = Math.ceil(file.size / PART_SIZE);\n    const parts = [];\n    const started = Date.now();\n    for (let i = 0; i < totalParts; i++) {\n      const chunk = file.slice(i * PART_SIZE, Math.min(file.size, (i + 1) * PART_SIZE));\n      let attempt = 0;\n      while (true) {\n        try {\n          const part = await apiJson(`api/videos/${videoId}/upload/part?uploadId=${encodeURIComponent(uploadId)}&part=${i + 1}`, {\n            method: 'PUT', headers: { 'Content-Type': 'application/octet-stream' }, body: chunk\n          });\n          parts.push({ partNumber: part.partNumber, etag: part.etag });\n          break;\n        } catch (err) {\n          if (++attempt >= 3) throw err;\n          setProgress(`Falha na parte ${i + 1}. Tentando de novo...`);\n          await new Promise(r => setTimeout(r, 2000 * attempt));\n        }\n      }\n      const sent = Math.min(file.size, (i + 1) * PART_SIZE);\n      const secs = (Date.now() - started) / 1000;\n      const rate = sent / Math.max(secs, 1);\n      const left = Math.round((file.size - sent) / Math.max(rate, 1) / 60);\n      setProgress(`Enviando ${Math.round(sent / file.size * 100)}% · ${formatBytes(sent)} de ${formatBytes(file.size)}${left > 0 ? ` · cerca de ${left} min restantes` : ''}. Mantenha esta página aberta.`);\n    }\n\n    await apiJson(`api/videos/${videoId}/upload/complete`, {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ uploadId, parts, duration: info.duration, width: info.width, height: info.height })\n    });\n\n    setProgress('Filme publicado.');\n    showToast('Filme enviado e publicado!');\n    document.getElementById('uploadForm').reset();\n    selectedVideoFile = null; selectedPosterFile = null;\n    ['videoDrop', 'posterDrop'].forEach(id => {\n      const elx = document.getElementById(id);\n      elx.classList.remove('has-file'); delete elx.dataset.filled;\n    });\n    document.getElementById('videoDrop').textContent = 'Arraste o vídeo aqui ou clique para escolher';\n    document.getElementById('posterDrop').textContent = 'Arraste a capa aqui ou clique para escolher';\n  } catch (err) {\n    setProgress(`O envio parou: ${err.message}`);\n    showToast(err.message);\n    if (videoId) {\n      await fetch(`api/videos/${videoId}/upload/abort`, {\n        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ uploadId })\n      }).catch(() => {});\n    }\n  } finally {\n    uploadInProgress = false;\n    submitBtn.disabled = false;\n    submitBtn.textContent = 'Enviar filme';\n    loadVideos();\n  }\n});\n\nfunction statusPill(status) {\n  if (status === 'ready') return `<span class=\"status-pill ready\">pronto</span>`;\n  if (status === 'error') return `<span class=\"status-pill error\">envio interrompido</span>`;\n  if (status === 'uploading') return `<span class=\"status-pill processing\">enviando</span>`;\n  return `<span class=\"status-pill processing\">${status}</span>`;\n}\n\nasync function loadVideos() {\n  const res = await fetch('api/videos');\n  const videos = await res.json();\n  const tbody = document.querySelector('#videosTable tbody');\n  tbody.innerHTML = videos.map(v => `\n    <tr>\n      <td>${v.title}</td>\n      <td>${v.category}</td>\n      <td>${v.orientation === 'vertical' ? '📱 Capa' : '🎬 Filme'}</td>\n      <td>${ownerLabel(v.owner_user_id)}</td>\n      <td>${statusPill(v.status)}</td>\n      <td>${v.max_quality || '—'}</td>\n      <td><button class=\"icon-btn\" onclick=\"deleteVideo(${v.id}, '${v.title.replace(/'/g, \"\\\\'\")}')\">Excluir</button></td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"7\" style=\"color:var(--ink-dim);\">Nenhum vídeo cadastrado ainda.</td></tr>`;\n\n  const stillProcessing = !uploadInProgress && videos.some(v => v.status === 'uploading');\n  if (stillProcessing && !pollTimer) pollTimer = setInterval(loadVideos, 4000);\n  else if (!stillProcessing && pollTimer) { clearInterval(pollTimer); pollTimer = null; }\n}\n\nwindow.deleteVideo = async (id, title) => {\n  if (!confirm(`Excluir \"${title}\"? Isso apaga o filme do R2 também.`)) return;\n  await fetch(`api/videos/${id}`, { method: 'DELETE' });\n  showToast('Excluído');\n  loadVideos();\n};\n\n// ---------- Álbuns ----------\ndocument.getElementById('albumForm').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const payload = {\n    title: document.getElementById('albumTitle').value,\n    category: document.getElementById('albumCategory').value,\n    description: document.getElementById('albumDescription').value,\n    ownerUserId: document.getElementById('albumOwner').value\n  };\n  const res = await fetch('api/albums', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify(payload)\n  });\n  const data = await res.json();\n  if (!res.ok) { showToast(data.error || 'Erro ao criar álbum'); return; }\n  showToast('Álbum criado! Agora adicione as fotos na lista abaixo.');\n  document.getElementById('albumForm').reset();\n  loadAlbums();\n  openPhotoUpload(data.id, payload.title);\n});\n\nasync function loadAlbums() {\n  const res = await fetch('api/albums');\n  const albums = await res.json();\n  const tbody = document.querySelector('#albumsTable tbody');\n  tbody.innerHTML = albums.map(a => `\n    <tr>\n      <td>${a.title}</td>\n      <td>${a.category}</td>\n      <td>${ownerLabel(a.owner_user_id)}</td>\n      <td id=\"photoCount-${a.id}\">…</td>\n      <td>\n        <button class=\"icon-btn\" style=\"color:var(--gold);\" onclick=\"openPhotoUpload(${a.id}, '${a.title.replace(/'/g, \"\\\\'\")}')\">+ fotos</button>\n        <a class=\"icon-btn\" style=\"color:var(--gold); text-decoration:none;\" href=\"album.html?id=${a.id}\" target=\"_blank\">ver</a>\n        <button class=\"icon-btn\" onclick=\"deleteAlbum(${a.id}, '${a.title.replace(/'/g, \"\\\\'\")}')\">excluir</button>\n      </td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"5\" style=\"color:var(--ink-dim);\">Nenhum álbum cadastrado ainda.</td></tr>`;\n\n  for (const a of albums) {\n    fetch(`api/albums/${a.id}`).then(r => r.json()).then(full => {\n      const cell = document.getElementById(`photoCount-${a.id}`);\n      if (cell) cell.textContent = full.allPhotosCount ?? 0;\n    });\n  }\n}\n\nwindow.openPhotoUpload = async (albumId, title) => {\n  activeAlbumIdForUpload = albumId;\n  document.getElementById('photoUploadArea').style.display = 'block';\n  document.getElementById('photoUploadAlbumTitle').textContent = title;\n  await loadSectionsForAlbum(albumId);\n  document.getElementById('photoUploadArea').scrollIntoView({ behavior: 'smooth', block: 'center' });\n};\n\nasync function loadSectionsForAlbum(albumId) {\n  const res = await fetch(`api/albums/${albumId}`);\n  const album = await res.json();\n  const select = document.getElementById('sectionSelect');\n  select.innerHTML = `<option value=\"\">Sem seção (fotos gerais)</option>` +\n    (album.sections || []).map(s => `<option value=\"${s.id}\">${s.title} (${s.photos.length} fotos)</option>`).join('');\n}\n\ndocument.getElementById('createSectionBtn').addEventListener('click', async () => {\n  const title = document.getElementById('newSectionTitle').value.trim();\n  if (!title || !activeAlbumIdForUpload) { showToast('Digite o nome da seção'); return; }\n  const res = await fetch(`api/albums/${activeAlbumIdForUpload}/sections`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ title })\n  });\n  const data = await res.json();\n  if (!res.ok) { showToast(data.error || 'Erro ao criar seção'); return; }\n  document.getElementById('newSectionTitle').value = '';\n  await loadSectionsForAlbum(activeAlbumIdForUpload);\n  document.getElementById('sectionSelect').value = data.id;\n  showToast(`Seção \"${title}\" criada — agora escolha as fotos e envie.`);\n});\n\ndocument.getElementById('cancelPhotoUpload').addEventListener('click', () => {\n  activeAlbumIdForUpload = null;\n  document.getElementById('photoUploadArea').style.display = 'none';\n  document.getElementById('photoFilesInput').value = '';\n});\n\ndocument.getElementById('uploadPhotosBtn').addEventListener('click', async () => {\n  const files = document.getElementById('photoFilesInput').files;\n  if (!files.length || !activeAlbumIdForUpload) { showToast('Escolha ao menos uma foto'); return; }\n  const albumId = activeAlbumIdForUpload;\n  const sectionId = document.getElementById('sectionSelect').value;\n  const btn = document.getElementById('uploadPhotosBtn');\n  btn.disabled = true;\n  uploadInProgress = true;\n  try {\n    const result = await window.studioUploadPhotos(`api/albums/${albumId}/files`, files, sectionId ? { section: sectionId } : {},\n      (done, total, failed) => { btn.textContent = `Enviando ${done} de ${total}${failed ? ` (${failed} com erro)` : ''}...`; });\n    showToast(result.failed ? `${result.done - result.failed} foto(s) enviadas, ${result.failed} com erro: ${result.errors[0]}` : `${result.done} foto(s) enviadas!`);\n    document.getElementById('photoFilesInput').value = '';\n    loadAlbums();\n    loadSectionsForAlbum(albumId);\n  } catch (err) {\n    showToast(err.message);\n  } finally {\n    uploadInProgress = false;\n    btn.disabled = false;\n    btn.textContent = 'Enviar fotos';\n  }\n});\n\nwindow.deleteAlbum = async (id, title) => {\n  if (!confirm(`Excluir álbum \"${title}\"? Isso remove todas as fotos do R2 também.`)) return;\n  await fetch(`api/albums/${id}`, { method: 'DELETE' });\n  showToast('Álbum excluído');\n  loadAlbums();\n};\n\n// ---------- Pacotes de serviço ----------\nfunction parsePackageItems(text) {\n  return text.split('\\n').map(l => l.trim()).filter(Boolean).map(line => {\n    const [label, priceStr, flag] = line.split('|').map(s => s.trim());\n    return {\n      label,\n      price: parseFloat((priceStr || '0').replace(',', '.')) || 0,\n      defaultIncluded: (flag || '').toLowerCase().startsWith('inclus')\n    };\n  });\n}\n\ndocument.getElementById('createPackageBtn').addEventListener('click', async () => {\n  const title = document.getElementById('packageTitle').value.trim();\n  const description = document.getElementById('packageDescription').value.trim();\n  const itemsText = document.getElementById('packageItems').value.trim();\n  if (!title) { showToast('Digite o título do pacote'); return; }\n\n  const items = itemsText ? parsePackageItems(itemsText) : [];\n  const res = await fetch('api/packages', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ title, description, items })\n  });\n  const data = await res.json();\n  if (!res.ok) { showToast(data.error || 'Erro ao criar pacote'); return; }\n\n  showToast('Pacote criado! Já aparece em /pacotes.html');\n  document.getElementById('packageTitle').value = '';\n  document.getElementById('packageDescription').value = '';\n  document.getElementById('packageItems').value = '';\n  loadPackages();\n});\n\nasync function loadPackages() {\n  const res = await fetch('api/packages');\n  if (!res.ok) return;\n  const packages = await res.json();\n  const tbody = document.querySelector('#packagesTable tbody');\n  tbody.innerHTML = packages.map(p => `\n    <tr>\n      <td>${p.title}</td>\n      <td>R$ ${p.basePrice.toFixed(2)}</td>\n      <td>${p.items.length}</td>\n      <td><button class=\"icon-btn\" onclick=\"deletePackage(${p.id}, '${p.title.replace(/'/g, \"\\\\'\")}')\">excluir</button></td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"4\" style=\"color:var(--ink-dim);\">Nenhum pacote cadastrado ainda.</td></tr>`;\n}\n\nwindow.deletePackage = async (id, title) => {\n  if (!confirm(`Excluir pacote \"${title}\"?`)) return;\n  await fetch(`api/packages/${id}`, { method: 'DELETE' });\n  showToast('Pacote excluído');\n  loadPackages();\n};\n\nasync function loadOrders() {\n  const res = await fetch('api/packages/orders/all');\n  if (!res.ok) return;\n  const orders = await res.json();\n  const tbody = document.querySelector('#ordersTable tbody');\n  const statusLabel = { approved: 'pago', pending: 'aguardando', rejected: 'recusado' };\n  const statusClass = { approved: 'ready', pending: 'processing', rejected: 'error' };\n  tbody.innerHTML = orders.map(o => `\n    <tr>\n      <td>${o.package_title}</td>\n      <td>${o.payer_name || '—'}<br><span style=\"color:var(--ink-dim); font-size:11px;\">${o.payer_email || ''}</span></td>\n      <td>R$ ${o.total.toFixed(2)}</td>\n      <td><span class=\"status-pill ${statusClass[o.status] || ''}\">${statusLabel[o.status] || o.status}</span></td>\n      <td>${new Date(o.created_at).toLocaleDateString('pt-BR')}</td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"5\" style=\"color:var(--ink-dim);\">Nenhuma venda ainda.</td></tr>`;\n}\n\n// ---------- Produtos físicos ----------\ndocument.getElementById('createProductBtn').addEventListener('click', async () => {\n  const title = document.getElementById('productTitle').value.trim();\n  const price = document.getElementById('productPrice').value;\n  const description = document.getElementById('productDescription').value.trim();\n  if (!title || !price) { showToast('Preencha nome e preço'); return; }\n  const res = await fetch('api/products', {\n    method: 'POST', headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ title, price, description })\n  });\n  const data = await res.json();\n  if (!res.ok) { showToast(data.error || 'Erro ao criar produto'); return; }\n  showToast('Produto adicionado à loja');\n  document.getElementById('productTitle').value = '';\n  document.getElementById('productPrice').value = '';\n  document.getElementById('productDescription').value = '';\n  loadProducts();\n});\n\nasync function loadProducts() {\n  const res = await fetch('api/products');\n  if (!res.ok) return;\n  const products = await res.json();\n  document.querySelector('#productsTable tbody').innerHTML = products.map(p => `\n    <tr>\n      <td>${p.title}</td>\n      <td>R$ ${p.price.toFixed(2)}</td>\n      <td><button class=\"icon-btn\" onclick=\"deleteProduct(${p.id}, '${p.title.replace(/'/g, \"\\\\'\")}')\">excluir</button></td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"3\" style=\"color:var(--ink-dim);\">Nenhum produto cadastrado ainda.</td></tr>`;\n}\n\nwindow.deleteProduct = async (id, title) => {\n  if (!confirm(`Excluir \"${title}\" da loja?`)) return;\n  await fetch(`api/products/${id}`, { method: 'DELETE' });\n  loadProducts();\n};\n\nasync function loadProductOrders() {\n  const res = await fetch('api/products/orders/all');\n  if (!res.ok) return;\n  const orders = await res.json();\n  const statusLabel = { approved: 'pago', pending: 'aguardando', rejected: 'recusado' };\n  const statusClass = { approved: 'ready', pending: 'processing', rejected: 'error' };\n  document.querySelector('#productOrdersTable tbody').innerHTML = orders.map(o => `\n    <tr>\n      <td>${o.product_title} (x${o.quantity})</td>\n      <td>${o.payer_name || '—'}<br><span style=\"color:var(--ink-dim); font-size:11px;\">${o.payer_email || ''}</span></td>\n      <td>R$ ${o.total.toFixed(2)}</td>\n      <td><span class=\"status-pill ${statusClass[o.status] || ''}\">${statusLabel[o.status] || o.status}</span></td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"4\" style=\"color:var(--ink-dim);\">Nenhum pedido ainda.</td></tr>`;\n}\n\n// ---------- Depoimentos ----------\nasync function loadTestimonials() {\n  const res = await fetch('api/testimonials');\n  if (!res.ok) return;\n  const rows = await res.json();\n  document.querySelector('#testimonialsTable tbody').innerHTML = rows.map(t => `\n    <tr>\n      <td>${t.client_name}<br><span style=\"color:var(--ink-dim); font-size:11px;\">${t.owner_email}</span></td>\n      <td style=\"max-width:260px;\">${t.quote}</td>\n      <td><span class=\"status-pill ${t.approved ? 'ready' : 'processing'}\">${t.approved ? 'publicado' : 'pendente'}</span></td>\n      <td>\n        ${!t.approved ? `<button class=\"icon-btn\" style=\"color:var(--gold);\" onclick=\"approveTestimonial(${t.id})\">aprovar</button>` : ''}\n        <button class=\"icon-btn\" onclick=\"deleteTestimonial(${t.id})\">excluir</button>\n      </td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"4\" style=\"color:var(--ink-dim);\">Nenhum depoimento recebido ainda.</td></tr>`;\n}\n\nwindow.approveTestimonial = async (id) => {\n  await fetch(`api/testimonials/${id}/approve`, { method: 'PATCH' });\n  showToast('Depoimento publicado no portfólio!');\n  loadTestimonials();\n};\nwindow.deleteTestimonial = async (id) => {\n  if (!confirm('Excluir este depoimento?')) return;\n  await fetch(`api/testimonials/${id}`, { method: 'DELETE' });\n  loadTestimonials();\n};\n\n// ---------- Contratos ----------\nfunction parseEventsText(text) {\n  const blocks = text.split(/\\n\\s*\\n/).map(b => b.trim()).filter(Boolean);\n  return blocks.map(block => {\n    const lines = block.split('\\n').map(l => l.trim()).filter(Boolean);\n    const [titlePart, ...rest] = lines;\n    const [title, date] = titlePart.split('|').map(s => s.trim());\n    return { title, event_date: date || '', items: rest };\n  });\n}\n\ndocument.getElementById('createContractBtn').addEventListener('click', async () => {\n  const ownerUserId = document.getElementById('contractOwner').value;\n  const title = document.getElementById('contractTitle').value.trim();\n  const body = document.getElementById('contractBody').value.trim();\n  const eventsText = document.getElementById('contractEvents').value.trim();\n\n  if (!ownerUserId || !title) { showToast('Selecione o cliente e o título'); return; }\n\n  const events = eventsText ? parseEventsText(eventsText) : [];\n  const res = await fetch('api/contracts', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ ownerUserId, title, body, events })\n  });\n  const data = await res.json();\n  if (!res.ok) { showToast(data.error || 'Erro ao criar contrato'); return; }\n\n  showToast('Contrato criado! O cliente já pode assinar na área dele.');\n  document.getElementById('contractTitle').value = '';\n  document.getElementById('contractBody').value = '';\n  document.getElementById('contractEvents').value = '';\n  loadContracts();\n});\n\nasync function loadContracts() {\n  const res = await fetch('api/contracts');\n  if (!res.ok) return;\n  const contracts = await res.json();\n  const tbody = document.querySelector('#contractsTable tbody');\n  tbody.innerHTML = contracts.map(c => `\n    <tr>\n      <td>${c.title}</td>\n      <td>${c.owner_email}</td>\n      <td><span class=\"status-pill ${c.status === 'signed' ? 'ready' : 'processing'}\">${c.status === 'signed' ? 'assinado' : 'pendente'}</span></td>\n      <td>\n        <a class=\"icon-btn\" style=\"color:var(--gold); text-decoration:none;\" href=\"contract.html?id=${c.id}\" target=\"_blank\">ver</a>\n        <button class=\"icon-btn\" onclick=\"deleteContract(${c.id}, '${c.title.replace(/'/g, \"\\\\'\")}')\">excluir</button>\n      </td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"4\" style=\"color:var(--ink-dim);\">Nenhum contrato cadastrado ainda.</td></tr>`;\n}\n\nwindow.deleteContract = async (id, title) => {\n  if (!confirm(`Excluir contrato \"${title}\"?`)) return;\n  await fetch(`api/contracts/${id}`, { method: 'DELETE' });\n  showToast('Contrato excluído');\n  loadContracts();\n};\n\n// ---------- Contas de clientes ----------\ndocument.getElementById('userForm').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const email = document.getElementById('userEmail').value;\n  const password = document.getElementById('userPassword').value;\n  try {\n    const res = await fetch('api/auth/users', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ email, password })\n    });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error);\n    showToast(data.existed ? 'Esse e-mail já tinha conta: o acesso ao Studio foi liberado com a senha atual dele.' : 'Cliente criado! Envie o e-mail e a senha pra ele.');\n    document.getElementById('userForm').reset();\n    loadUsers();\n    loadClientsForDropdowns();\n  } catch (err) {\n    showToast(err.message);\n  }\n});\n\nasync function loadUsers() {\n  const res = await fetch('api/auth/users');\n  const users = await res.json();\n  const tbody = document.querySelector('#usersTable tbody');\n  const list = users.filter(u => !u.is_admin);\n  tbody.innerHTML = list.map(u => `\n    <tr>\n      <td>${u.email}</td>\n      <td>${new Date(u.created_at).toLocaleDateString('pt-BR')}</td>\n      <td><button class=\"icon-btn\" onclick=\"deleteUser('${u.id}', '${u.email}')\">Remover acesso</button></td>\n    </tr>\n  `).join('') || `<tr><td colspan=\"3\" style=\"color:var(--ink-dim);\">Nenhum cliente cadastrado ainda.</td></tr>`;\n}\n\nwindow.deleteUser = async (id, email) => {\n  if (!confirm(`Remover o acesso de ${email} ao Studio?`)) return;\n  await fetch(`api/auth/users/${id}`, { method: 'DELETE' });\n  loadUsers();\n  loadClientsForDropdowns();\n};\n\n(async () => {\n  const user = await requireSession();\n  if (!user.isAdmin) { window.location.href = 'index.html'; return; }\n  await loadClientsForDropdowns();\n  loadVideos();\n  loadAlbums();\n  loadPackages();\n  loadOrders();\n  loadProducts();\n  loadProductOrders();\n  loadTestimonials();\n  loadContracts();\n  loadUsers();\n})();\n","etag":"\"3774cf8c3b6d8c54\""},"js/album.js":{"body":"let albumData = null;\nlet currentPhotoIndex = 0;\nlet canDownload = false;\n\nfunction el(id) { return document.getElementById(id); }\n\nasync function loadAlbum() {\n  const params = new URLSearchParams(window.location.search);\n  const albumId = params.get('id');\n  if (!albumId) { window.location.href = './'; return; }\n\n  const user = await trySession();\n  el('backLink').href = user ? 'index.html' : './';\n\n  const res = await fetch(`api/albums/${albumId}`);\n  if (res.status === 403) {\n    document.querySelector('main').innerHTML = '';\n    el('albumHeader').innerHTML = `\n      <div style=\"text-align:center; padding:60px 20px;\">\n        <h1 style=\"font-size:22px;\">Este álbum é privado</h1>\n        <p style=\"color:var(--ink-dim); margin:10px 0 20px;\">Faça login com a conta do cliente pra ver as fotos.</p>\n        <a class=\"btn btn-primary\" href=\"login.html\">Entrar</a>\n      </div>`;\n    return;\n  }\n  if (!res.ok) { window.location.href = './'; return; }\n  albumData = await res.json();\n\n  const canInteract = !!user; // download/comentário exigem login; o backend valida propriedade de fato\n  canDownload = canInteract;\n\n  el('albumHeader').innerHTML = `\n    <div style=\"display:flex; align-items:flex-start; justify-content:space-between; gap:16px;\">\n      <div>\n        <h1>${albumData.title}</h1>\n        <p>${albumData.description || ''}</p>\n      </div>\n      <div style=\"display:flex; gap:8px; flex-shrink:0;\">\n        ${canInteract ? `<button class=\"photo-download-btn\" style=\"position:static; width:auto; min-width:38px; height:38px; font-size:16px; padding:0 10px;\" id=\"zipBtn\" title=\"Baixar álbum inteiro (.zip)\">⬇</button>` : ''}\n        ${canInteract ? `<button class=\"photo-download-btn\" style=\"position:static; width:38px; height:38px; font-size:15px;\" id=\"manageToggleBtn\" title=\"Compartilhar e convidados\">⚙</button>` : ''}\n      </div>\n    </div>\n  `;\n\n  if (canInteract) setupManagePanel();\n  const zipBtn = document.getElementById('zipBtn');\n  if (zipBtn) zipBtn.addEventListener('click', () => downloadAlbumZip(zipBtn));\n\n  function photoGridHTML(photos) {\n    if (!photos.length) return '';\n    return `<div class=\"photo-grid\">${photos.map(p => {\n      const globalIndex = albumData.__flatPhotos.findIndex(fp => fp.id === p.id);\n      return `\n        <div class=\"photo-thumb\" style=\"background-image:url('${p.thumb_url}')\" onclick=\"openLightbox(${globalIndex})\">\n          ${canInteract ? `<a class=\"photo-download-btn\" href=\"${p.download_url}\" onclick=\"event.stopPropagation()\" title=\"Baixar esta foto\">⬇</a>` : ''}\n        </div>`;\n    }).join('')}</div>`;\n  }\n\n  // Lista \"achatada\" de todas as fotos (seções + gerais), na ordem em que aparecem na página — usada pra navegação da ampliação\n  albumData.__flatPhotos = [\n    ...albumData.sections.flatMap(s => s.photos),\n    ...albumData.photos\n  ];\n\n  let bodyHTML = '';\n  for (const section of albumData.sections) {\n    if (!section.photos.length) continue;\n    bodyHTML += `\n      <div class=\"section-block\">\n        <div class=\"section-banner\" style=\"background-image:url('${section.cover_url || ''}'); position:relative;\">\n          ${canInteract ? `<button class=\"section-share-btn\" onclick=\"shareSection(${section.id})\" title=\"Compartilhar esta seção\">🔗</button>` : ''}\n          <div class=\"section-banner-text\">\n            <h2>${section.title}</h2>\n            ${section.description ? `<p>${section.description}</p>` : ''}\n          </div>\n        </div>\n        ${photoGridHTML(section.photos)}\n      </div>\n    `;\n  }\n  if (albumData.photos.length) {\n    bodyHTML += albumData.sections.length\n      ? `<div class=\"section-block\"><div class=\"section-heading-simple\"><h2>Fotos gerais</h2></div>${photoGridHTML(albumData.photos)}</div>`\n      : photoGridHTML(albumData.photos);\n  }\n\n  document.getElementById('photoGrid').outerHTML = `<main id=\"photoGrid\">${bodyHTML || '<div class=\"empty-state\"><h2>Nenhuma foto neste álbum ainda</h2></div>'}</main>`;\n\n  if (canInteract) {\n    el('albumComments').style.display = 'block';\n    loadComments();\n  }\n}\n\n// Monta o .zip do álbum no próprio navegador, sem compressão (fotos já são comprimidas)\nasync function downloadAlbumZip(btn) {\n  const photos = albumData.__flatPhotos;\n  if (!photos.length) return;\n  if (!window.JSZip) { alert('Não foi possível preparar o download. Recarregue a página.'); return; }\n  const totalBytes = photos.reduce((sum, p) => sum + (p.size_bytes || 0), 0);\n  if (totalBytes > 1.8 * 1024 ** 3) {\n    alert('Este álbum é grande demais para baixar de uma vez só pelo navegador. Baixe as fotos pelas setas ⬇ de cada uma ou peça o link completo à Duna.');\n    return;\n  }\n  btn.disabled = true;\n  const zip = new JSZip();\n  const used = new Set();\n  let done = 0, next = 0;\n  async function worker() {\n    while (next < photos.length) {\n      const index = next++;\n      const photo = photos[index];\n      const res = await fetch(photo.url);\n      if (!res.ok) throw new Error('Falha ao baixar uma das fotos. Recarregue a página e tente de novo.');\n      let name = photo.original_name || `foto-${index + 1}.jpg`;\n      if (used.has(name)) name = `${index + 1}-${name}`;\n      used.add(name);\n      zip.file(name, await res.blob(), { binary: true });\n      btn.textContent = `${++done}/${photos.length}`;\n    }\n  }\n  try {\n    await Promise.all([worker(), worker(), worker(), worker()]);\n    btn.textContent = 'zip…';\n    const blob = await zip.generateAsync({ type: 'blob', compression: 'STORE', streamFiles: true });\n    const link = document.createElement('a');\n    link.href = URL.createObjectURL(blob);\n    link.download = `${albumData.title.replace(/[^\\w\\-]+/g, '_')}.zip`;\n    document.body.appendChild(link);\n    link.click();\n    setTimeout(() => { URL.revokeObjectURL(link.href); link.remove(); }, 60000);\n  } catch (err) {\n    alert(err.message);\n  } finally {\n    btn.disabled = false;\n    btn.textContent = '⬇';\n  }\n}\n\nfunction setupManagePanel() {\n  const btn = document.getElementById('manageToggleBtn');\n  if (!btn) return;\n  btn.addEventListener('click', async () => {\n    const panel = el('managePanel');\n    if (panel.style.display === 'none') {\n      panel.innerHTML = `\n        <h3>Compartilhar álbum inteiro</h3>\n        <div class=\"manage-row\">\n          <label><input type=\"checkbox\" id=\"albumAllowDownload\"> Permitir que quem receber o link também baixe as fotos</label>\n        </div>\n        <div class=\"manage-row\">\n          <button class=\"btn btn-ghost\" id=\"genAlbumLinkBtn\">Gerar / atualizar link</button>\n          <div class=\"manage-link-box\" id=\"albumLinkBox\" style=\"display:none; flex:1;\"></div>\n        </div>\n        <h3 style=\"margin-top:18px;\">Convidados podem enviar fotos</h3>\n        <div class=\"manage-row\">\n          <label><input type=\"checkbox\" id=\"guestUploadToggle\"> Ativar upload dos convidados (link pra festa)</label>\n        </div>\n        <div class=\"manage-link-box\" id=\"guestLinkBox\" style=\"display:none;\"></div>\n      `;\n      document.getElementById('genAlbumLinkBtn').addEventListener('click', async () => {\n        const allow = document.getElementById('albumAllowDownload').checked;\n        const res = await fetch(`api/albums/${albumData.id}/share`, {\n          method: 'POST', headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ allowDownload: allow })\n        });\n        const data = await res.json();\n        if (res.ok) {\n          const url = `${window.location.href.replace(/[^/]*$/, \"\")}compartilhado.html?t=${data.token}`;\n          const box = document.getElementById('albumLinkBox');\n          box.style.display = 'block';\n          box.innerHTML = `${url} <button class=\"icon-btn\" style=\"color:var(--gold);\" onclick=\"navigator.clipboard.writeText('${url}'); this.textContent='copiado!'\">copiar</button>`;\n        }\n      });\n      document.getElementById('guestUploadToggle').addEventListener('change', async (e) => {\n        const res = await fetch(`api/albums/${albumData.id}/guest-upload/toggle`, {\n          method: 'POST', headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ enabled: e.target.checked })\n        });\n        const data = await res.json();\n        const box = document.getElementById('guestLinkBox');\n        if (data.token) {\n          const url = `${window.location.href.replace(/[^/]*$/, \"\")}convidados.html?t=${data.token}`;\n          box.style.display = 'block';\n          box.innerHTML = `${url} <button class=\"icon-btn\" style=\"color:var(--gold);\" onclick=\"navigator.clipboard.writeText('${url}'); this.textContent='copiado!'\">copiar</button>`;\n        } else {\n          box.style.display = 'none';\n        }\n      });\n      panel.style.display = 'block';\n    } else {\n      panel.style.display = 'none';\n    }\n  });\n}\n\nwindow.shareSection = async (sectionId) => {\n  const allow = confirm('Permitir que quem receber o link também baixe as fotos desta seção?\\n\\nOK = sim, permitir download\\nCancelar = só visualização');\n  const res = await fetch(`api/albums/${albumData.id}/sections/${sectionId}/share`, {\n    method: 'POST', headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ allowDownload: allow })\n  });\n  const data = await res.json();\n  if (res.ok) {\n    const url = `${window.location.href.replace(/[^/]*$/, \"\")}compartilhado.html?t=${data.token}`;\n    navigator.clipboard.writeText(url).catch(() => {});\n    alert(`Link copiado!\\n\\n${url}`);\n  }\n};\n\n// ---------- Pedido de produto físico ----------\nasync function openOrderPanel(photo) {\n  const res = await fetch('api/products');\n  const products = res.ok ? await res.json() : [];\n  const panel = el('orderPanel');\n\n  if (!products.length) {\n    panel.innerHTML = `<div class=\"order-panel-inner\"><p>Nenhum produto disponível no momento.</p><button class=\"btn btn-ghost\" onclick=\"document.getElementById('orderPanel').style.display='none'\">Fechar</button></div>`;\n    panel.style.display = 'flex';\n    return;\n  }\n\n  panel.innerHTML = `\n    <div class=\"order-panel-inner\">\n      <h3>Pedir produto físico</h3>\n      ${products.map(p => `\n        <div class=\"product-option\">\n          <span>${p.title}</span>\n          <span class=\"price\">R$ ${p.price.toFixed(2)}</span>\n        </div>\n      `).join('')}\n      <div class=\"field\" style=\"margin-top:14px;\"><label>Produto</label>\n        <select id=\"orderProduct\">${products.map(p => `<option value=\"${p.id}\" data-price=\"${p.price}\">${p.title} — R$ ${p.price.toFixed(2)}</option>`).join('')}</select>\n      </div>\n      <div class=\"field\"><label>Quantidade</label><input type=\"number\" id=\"orderQty\" value=\"1\" min=\"1\"></div>\n      <div class=\"field\"><label>Seu nome</label><input type=\"text\" id=\"orderName\"></div>\n      <div class=\"field\"><label>Seu e-mail</label><input type=\"email\" id=\"orderEmail\" required></div>\n      <button class=\"btn btn-primary\" style=\"width:100%; justify-content:center;\" id=\"confirmOrderBtn\">Ir para o pagamento →</button>\n      <button class=\"btn btn-ghost\" style=\"width:100%; justify-content:center; margin-top:8px;\" onclick=\"document.getElementById('orderPanel').style.display='none'\">Cancelar</button>\n    </div>\n  `;\n  panel.style.display = 'flex';\n\n  document.getElementById('confirmOrderBtn').addEventListener('click', async () => {\n    const productId = document.getElementById('orderProduct').value;\n    const quantity = document.getElementById('orderQty').value;\n    const payerName = document.getElementById('orderName').value.trim();\n    const payerEmail = document.getElementById('orderEmail').value.trim();\n    if (!payerEmail) { alert('Digite seu e-mail.'); return; }\n\n    const btn = document.getElementById('confirmOrderBtn');\n    btn.disabled = true; btn.textContent = 'Redirecionando...';\n    try {\n      const res = await fetch(`api/products/${productId}/order`, {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ photoId: photo.id, albumId: albumData.id, quantity, payerName, payerEmail })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Erro ao criar pedido');\n      window.location.href = data.checkoutUrl;\n    } catch (err) {\n      alert(err.message);\n      btn.disabled = false; btn.textContent = 'Ir para o pagamento →';\n    }\n  });\n}\n\nfunction openLightbox(index) {\n  currentPhotoIndex = index;\n  renderLightbox();\n  el('lightbox').classList.add('open');\n}\n\nfunction renderLightbox() {\n  const photo = albumData.__flatPhotos[currentPhotoIndex];\n  el('lightboxImg').src = photo.url;\n  el('lightboxDownload').style.display = canDownload ? 'inline-flex' : 'none';\n  el('lightboxDownload').onclick = () => {\n    window.location.href = photo.download_url;\n  };\n  el('lightboxOrder').onclick = () => openOrderPanel(photo);\n}\n\nel('lightboxClose').addEventListener('click', () => el('lightbox').classList.remove('open'));\nel('lightboxPrev').addEventListener('click', () => {\n  currentPhotoIndex = (currentPhotoIndex - 1 + albumData.__flatPhotos.length) % albumData.__flatPhotos.length;\n  renderLightbox();\n});\nel('lightboxNext').addEventListener('click', () => {\n  currentPhotoIndex = (currentPhotoIndex + 1) % albumData.__flatPhotos.length;\n  renderLightbox();\n});\nel('lightbox').addEventListener('click', (e) => {\n  if (e.target.id === 'lightbox') el('lightbox').classList.remove('open');\n});\ndocument.addEventListener('keydown', (e) => {\n  if (!el('lightbox').classList.contains('open')) return;\n  if (e.key === 'Escape') el('lightbox').classList.remove('open');\n  if (e.key === 'ArrowLeft') el('lightboxPrev').click();\n  if (e.key === 'ArrowRight') el('lightboxNext').click();\n});\n\nasync function loadComments() {\n  const res = await fetch(`api/albums/${albumData.id}/comments`);\n  if (!res.ok) { el('albumComments').style.display = 'none'; return; }\n  const comments = await res.json();\n  el('commentsList').innerHTML = comments.length\n    ? comments.map(c => `\n        <div class=\"comment-item\">\n          <div>${c.body}</div>\n          <div class=\"meta\">${c.author} · ${new Date(c.created_at).toLocaleString('pt-BR')}</div>\n        </div>\n      `).join('')\n    : `<p style=\"color:var(--ink-dim); font-size:14px;\">Nenhum comentário ainda.</p>`;\n}\n\nel('commentForm').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const body = el('commentInput').value.trim();\n  if (!body) return;\n  const res = await fetch(`api/albums/${albumData.id}/comments`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ body })\n  });\n  if (res.ok) {\n    el('commentInput').value = '';\n    loadComments();\n  } else {\n    const data = await res.json();\n    alert(data.error || 'Erro ao comentar');\n  }\n});\n\nwindow.openLightbox = openLightbox;\nloadAlbum();\n","etag":"\"0e7d3a36f41d0396\""},"js/app.js":{"body":"function formatDuration(seconds) {\n  if (!seconds) return '';\n  const h = Math.floor(seconds / 3600);\n  const m = Math.round((seconds % 3600) / 60);\n  return h > 0 ? `${h}h ${m}min` : `${m}min`;\n}\n\nfunction progressFor(videoId) {\n  try {\n    const raw = localStorage.getItem('wf_progress_' + videoId);\n    return raw ? JSON.parse(raw) : null;\n  } catch { return null; }\n}\n\n// ---------- Hero rotativo: toca as capas verticais em sequência ----------\nlet heroReels = [];\nlet heroIndex = 0;\n\nfunction heroMarkup(video) {\n  return `\n    <section class=\"hero\">\n      <video class=\"hero-bg\" id=\"heroVideo\" muted autoplay playsinline></video>\n      <div class=\"hero-content\">\n        <div class=\"category\">${video.category}</div>\n        <h1 id=\"heroTitle\">${video.title}</h1>\n        <p id=\"heroDesc\">${video.description || ''}</p>\n        <a class=\"btn btn-primary\" id=\"heroCta\" href=\"watch.html?id=${video.id}\">▶ Assistir completo</a>\n      </div>\n      <div class=\"hero-dots\" id=\"heroDots\"></div>\n    </section>\n  `;\n}\n\nfunction renderHeroDots() {\n  const dots = document.getElementById('heroDots');\n  if (!dots || heroReels.length < 2) { if (dots) dots.innerHTML = ''; return; }\n  dots.innerHTML = heroReels.map((_, i) =>\n    `<button class=\"${i === heroIndex ? 'active' : ''}\" onclick=\"window.__heroGoTo(${i})\"></button>`\n  ).join('');\n}\n\nfunction loadHeroVideo(index) {\n  heroIndex = index;\n  const video = heroReels[heroIndex];\n  const videoEl = document.getElementById('heroVideo');\n  document.getElementById('heroTitle').textContent = video.title;\n  document.getElementById('heroDesc').textContent = video.description || '';\n  document.getElementById('heroCta').href = `watch.html?id=${video.id}`;\n  renderHeroDots();\n\n  videoEl.src = video.video_url;\n  videoEl.play().catch(() => {});\n}\n\nwindow.__heroGoTo = (i) => loadHeroVideo(i);\n\nfunction advanceHero() {\n  const next = (heroIndex + 1) % heroReels.length;\n  loadHeroVideo(next);\n}\n\nfunction renderHero(reelVideos, fallbackVideo) {\n  const section = document.getElementById('heroSection');\n\n  // Sem capas verticais prontas: usa a mesma estrutura, mas com imagem estática (comportamento original)\n  if (!reelVideos.length) {\n    if (!fallbackVideo) { section.innerHTML = ''; return; }\n    section.innerHTML = `\n      <section class=\"hero\" style=\"background-image:url('${fallbackVideo.poster_url || ''}'); background-size:cover; background-position:center;\">\n        <div class=\"hero-content\">\n          <div class=\"category\">${fallbackVideo.category}</div>\n          <h1>${fallbackVideo.title}</h1>\n          <p>${fallbackVideo.description || ''}</p>\n          <a class=\"btn btn-primary\" href=\"watch.html?id=${fallbackVideo.id}\">▶ Assistir</a>\n        </div>\n      </section>\n    `;\n    return;\n  }\n\n  heroReels = reelVideos;\n  section.innerHTML = heroMarkup(reelVideos[0]);\n  const videoEl = document.getElementById('heroVideo');\n  videoEl.addEventListener('ended', advanceHero);\n  loadHeroVideo(0);\n}\n\n// ---------- Filmes horizontais (carrosséis por categoria) ----------\nfunction cardHTML(video) {\n  const isReady = video.status === 'ready';\n  const progress = progressFor(video.id);\n  let progressBar = '';\n  if (progress && progress.pct > 3 && progress.pct < 95) {\n    progressBar = `<div style=\"height:3px;background:rgba(255,255,255,0.15);margin-top:6px;border-radius:2px;overflow:hidden;\">\n      <div style=\"height:100%;width:${progress.pct}%;background:var(--gold);\"></div></div>`;\n  }\n  return `\n    <a class=\"card\" href=\"${isReady ? `watch.html?id=${video.id}` : '#'}\" ${isReady ? '' : 'onclick=\"return false;\"'}>\n      <div class=\"card-thumb\" style=\"background-image:url('${video.poster_url || ''}')\">\n        ${video.max_quality ? `<span class=\"badge\">${video.max_quality}</span>` : ''}\n        ${!isReady ? `<div class=\"processing\">${video.status.startsWith('processing') ? 'Processando ' + video.status.split(':')[1] : 'Aguardando processamento'}</div>` : ''}\n      </div>\n      <div class=\"card-title\">${video.title}</div>\n      <div class=\"card-meta\">${formatDuration(video.duration_seconds)}</div>\n      ${progressBar}\n    </a>\n  `;\n}\n\nfunction albumCardHTML(album) {\n  return `\n    <a class=\"card\" href=\"album.html?id=${album.id}\">\n      <div class=\"card-thumb\" style=\"background-image:url('${album.cover_url || ''}')\">\n        <span class=\"badge\">📷 Álbum</span>\n      </div>\n      <div class=\"card-title\">${album.title}</div>\n    </a>\n  `;\n}\n\nfunction contractCardHTML(contract) {\n  const isSigned = contract.status === 'signed';\n  return `\n    <a class=\"card\" href=\"contract.html?id=${contract.id}\">\n      <div class=\"card-thumb\" style=\"background:var(--surface); display:flex; align-items:center; justify-content:center; font-size:34px;\">\n        📄\n        <span class=\"badge\" style=\"background:${isSigned ? 'rgba(90,160,90,0.85)' : 'rgba(201,161,90,0.85)'}; color:#0d1420;\">${isSigned ? 'Assinado' : 'Pendente'}</span>\n      </div>\n      <div class=\"card-title\">${contract.title}</div>\n    </a>\n  `;\n}\n\nasync function loadCatalog() {\n  const [videosRes, albumsRes, contractsRes] = await Promise.all([\n    fetch('api/videos'),\n    fetch('api/albums'),\n    fetch('api/contracts/mine')\n  ]);\n  if (!videosRes.ok) return;\n  const videos = await videosRes.json();\n  const albums = albumsRes.ok ? await albumsRes.json() : [];\n  const contracts = contractsRes.ok ? await contractsRes.json() : [];\n  const rowsEl = document.getElementById('rows');\n\n  const readyReels = videos.filter(v => v.orientation === 'vertical' && v.status === 'ready');\n  const filmVideos = videos.filter(v => v.orientation !== 'vertical');\n  const readyFilms = filmVideos.filter(v => v.status === 'ready');\n\n  renderHero(readyReels, readyFilms[0] || filmVideos[0]);\n\n  if (filmVideos.length === 0 && albums.length === 0 && contracts.length === 0) {\n    rowsEl.innerHTML = readyReels.length ? '' : `<div class=\"empty-state\">\n      <h2>Sua entrega ainda não chegou por aqui</h2>\n      <p>Assim que seu filme ou álbum for publicado pelo fotógrafo, ele aparece nesta página.</p>\n    </div>`;\n    return;\n  }\n\n  let html = '';\n\n  if (contracts.length) {\n    html += `\n      <div class=\"row\">\n        <div class=\"row-header\"><h2>Contrato</h2></div>\n        <div class=\"row-track\">${contracts.map(contractCardHTML).join('')}</div>\n      </div>\n    `;\n  }\n\n  if (filmVideos.length) {\n    const byCategory = {};\n    for (const v of filmVideos) { (byCategory[v.category] ||= []).push(v); }\n    html += Object.entries(byCategory).map(([category, list]) => `\n      <div class=\"row\">\n        <div class=\"row-header\"><h2>${category}</h2></div>\n        <div class=\"row-track\">${list.map(cardHTML).join('')}</div>\n      </div>\n    `).join('');\n  }\n\n  if (albums.length) {\n    html += `\n      <div class=\"row\">\n        <div class=\"row-header\"><h2>Álbuns de fotos</h2></div>\n        <div class=\"albums-grid\">${albums.map(albumCardHTML).join('')}</div>\n      </div>\n    `;\n  }\n\n  rowsEl.innerHTML = html;\n}\n\n(async () => {\n  await requireSession();\n  loadCatalog();\n})();\n","etag":"\"005a37ad7307767f\""},"js/auth-guard.js":{"body":"// Verifica sessão antes de renderizar a página; redireciona pro login se necessário.\nwindow.CURRENT_USER = null;\n\nasync function requireSession() {\n  try {\n    const res = await fetch('api/auth/me');\n    if (!res.ok) throw new Error();\n    const user = await res.json();\n    window.CURRENT_USER = user;\n    const adminLink = document.getElementById('adminLink');\n    if (adminLink && user.isAdmin) adminLink.style.display = 'block';\n    return user;\n  } catch {\n    window.location.href = 'login.html';\n    throw new Error('redirecting');\n  }\n}\n\n// Versão que NÃO redireciona — usada em páginas públicas (portfólio, vídeo/álbum públicos)\nasync function trySession() {\n  try {\n    const res = await fetch('api/auth/me');\n    if (!res.ok) throw new Error();\n    const user = await res.json();\n    window.CURRENT_USER = user;\n    const adminLink = document.getElementById('adminLink');\n    if (adminLink && user.isAdmin) adminLink.style.display = 'block';\n    return user;\n  } catch {\n    window.CURRENT_USER = null;\n    return null;\n  }\n}\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  const logoutBtn = document.getElementById('logoutBtn');\n  if (logoutBtn) {\n    logoutBtn.addEventListener('click', async () => {\n      const client = await window.studioReady;\n      if (client) await client.auth.signOut().catch(() => {});\n      window.location.href = 'login.html';\n    });\n  }\n\n  // Menu símbolo (☰) no topbar — abre/fecha o dropdown de navegação\n  const menuToggle = document.getElementById('menuToggle');\n  const menuDropdown = document.getElementById('menuDropdown');\n  if (menuToggle && menuDropdown) {\n    menuToggle.addEventListener('click', (e) => {\n      e.stopPropagation();\n      menuDropdown.classList.toggle('open');\n    });\n    document.addEventListener('click', (e) => {\n      if (!menuDropdown.contains(e.target) && e.target !== menuToggle) {\n        menuDropdown.classList.remove('open');\n      }\n    });\n  }\n});\n","etag":"\"1e7aa0625db66257\""},"js/compartilhado.js":{"body":"let shareData = null;\nlet currentIndex = 0;\nfunction el(id) { return document.getElementById(id); }\n\nasync function load() {\n  const params = new URLSearchParams(window.location.search);\n  const token = params.get('t');\n  if (!token) { el('albumHeader').innerHTML = '<p style=\"padding:0 40px; color:var(--ink-dim);\">Link inválido.</p>'; return; }\n\n  const res = await fetch(`api/albums/share/${token}`);\n  if (!res.ok) {\n    el('albumHeader').innerHTML = `<div style=\"text-align:center; padding:60px 20px;\"><h1 style=\"font-size:22px;\">Link inválido ou expirado</h1></div>`;\n    return;\n  }\n  shareData = await res.json();\n  shareData.__flat = [...shareData.sections.flatMap(s => s.photos), ...shareData.photos];\n\n  el('albumHeader').innerHTML = `<h1>${shareData.title}</h1><p>${shareData.description || ''}</p>`;\n\n  function grid(photos) {\n    if (!photos.length) return '';\n    return `<div class=\"photo-grid\">${photos.map(p => {\n      const i = shareData.__flat.findIndex(fp => fp.id === p.id);\n      return `<div class=\"photo-thumb\" style=\"background-image:url('${p.thumb_url}')\" onclick=\"openLightbox(${i})\">\n        ${shareData.allowDownload && p.download_url ? `<a class=\"photo-download-btn\" href=\"${p.download_url}\" onclick=\"event.stopPropagation()\" title=\"Baixar\">⬇</a>` : ''}\n      </div>`;\n    }).join('')}</div>`;\n  }\n\n  let html = '';\n  for (const s of shareData.sections) {\n    if (!s.photos.length) continue;\n    html += `<div class=\"section-block\">\n      <div class=\"section-banner\" style=\"background-image:url('${s.cover_url || ''}')\">\n        <div class=\"section-banner-text\"><h2>${s.title}</h2>${s.description ? `<p>${s.description}</p>` : ''}</div>\n      </div>${grid(s.photos)}</div>`;\n  }\n  if (shareData.photos.length) html += grid(shareData.photos);\n\n  document.getElementById('photoGrid').outerHTML = `<main id=\"photoGrid\">${html || '<div class=\"empty-state\"><h2>Nenhuma foto aqui ainda</h2></div>'}</main>`;\n}\n\nfunction openLightbox(i) {\n  currentIndex = i;\n  el('lightboxImg').src = shareData.__flat[i].url;\n  el('lightbox').classList.add('open');\n}\nwindow.openLightbox = openLightbox;\nel('lightboxClose').addEventListener('click', () => el('lightbox').classList.remove('open'));\nel('lightboxPrev').addEventListener('click', () => { currentIndex = (currentIndex - 1 + shareData.__flat.length) % shareData.__flat.length; el('lightboxImg').src = shareData.__flat[currentIndex].url; });\nel('lightboxNext').addEventListener('click', () => { currentIndex = (currentIndex + 1) % shareData.__flat.length; el('lightboxImg').src = shareData.__flat[currentIndex].url; });\n\nload();\n","etag":"\"4569574d2cc75792\""},"js/contract.js":{"body":"let currentContract = null;\nlet signaturePad = null;\nlet isDrawing = false;\nlet hasSignature = false;\n\nfunction el(id) { return document.getElementById(id); }\n\nasync function loadContract() {\n  const user = await requireSession();\n  const params = new URLSearchParams(window.location.search);\n  const idParam = params.get('id');\n\n  let contract;\n  if (idParam) {\n    const res = await fetch(`api/contracts/${idParam}`);\n    if (!res.ok) { renderEmpty(); return; }\n    contract = await res.json();\n  } else {\n    const res = await fetch('api/contracts/mine');\n    const list = res.ok ? await res.json() : [];\n    if (!list.length) { renderEmpty(); return; }\n    contract = list[0];\n  }\n\n  currentContract = contract;\n  render(contract, user);\n}\n\nfunction renderEmpty() {\n  el('contractWrap').innerHTML = `\n    <div class=\"empty-state\">\n      <h2>Nenhum contrato disponível</h2>\n      <p>Assim que o fotógrafo cadastrar seu contrato, ele aparece aqui.</p>\n    </div>`;\n}\n\nfunction render(contract, user) {\n  const isSigned = contract.status === 'signed';\n  const eventsHTML = contract.events.map(ev => `\n    <div class=\"contract-event\">\n      <h3>${ev.title}</h3>\n      ${ev.event_date ? `<div class=\"date\">${ev.event_date}</div>` : ''}\n      <ul>${ev.items.map(item => `<li>${item}</li>`).join('')}</ul>\n    </div>\n  `).join('') || '<p style=\"color:var(--ink-dim); font-size:13px;\">Nenhum evento detalhado neste contrato.</p>';\n\n  el('contractWrap').innerHTML = `\n    <h1>${contract.title}</h1>\n    <span class=\"contract-status ${isSigned ? 'signed' : 'pending'}\">${isSigned ? '✔ Assinado' : '⏳ Aguardando assinatura'}</span>\n\n    ${contract.body ? `<div class=\"contract-body\">${contract.body}</div>` : ''}\n\n    <h2 style=\"font-size:17px; margin-bottom:12px;\">Eventos contratados</h2>\n    ${eventsHTML}\n\n    <div id=\"signatureArea\"></div>\n  `;\n\n  if (isSigned) {\n    el('signatureArea').innerHTML = `\n      <div class=\"signed-block\">\n        <img src=\"${contract.signature_data_url}\" alt=\"Assinatura\">\n        <p style=\"font-size:13px; color:var(--ink-dim);\">Assinado por <b style=\"color:var(--ink);\">${contract.signer_name}</b><br>\n        em ${new Date(contract.signed_at).toLocaleString('pt-BR')}</p>\n        <button class=\"btn btn-primary\" id=\"pdfBtn\" type=\"button\" style=\"margin-top:14px;\">⬇ Baixar contrato (PDF)</button>\n      </div>\n    `;\n    el('pdfBtn').addEventListener('click', () => downloadPdf(contract));\n  } else if (!user.isAdmin) {\n    el('signatureArea').innerHTML = `\n      <div class=\"signature-pad-wrap\">\n        <label>Assine no campo abaixo (use o dedo ou o mouse)</label>\n        <canvas id=\"signaturePad\"></canvas>\n        <div class=\"field\" style=\"margin-top:14px;\">\n          <label>Seu nome completo</label>\n          <input type=\"text\" id=\"signerName\" placeholder=\"Nome como consta no contrato\">\n        </div>\n        <div class=\"signature-actions\">\n          <button class=\"btn btn-ghost\" id=\"clearSignatureBtn\" type=\"button\">Limpar</button>\n          <button class=\"btn btn-primary\" id=\"signBtn\" type=\"button\">Assinar contrato</button>\n        </div>\n      </div>\n    `;\n    setupSignaturePad();\n  } else {\n    el('signatureArea').innerHTML = `<p style=\"color:var(--ink-dim); font-size:13px;\">Aguardando o cliente assinar.</p>`;\n  }\n}\n\n// Gera o PDF do contrato no navegador (mesmo conteúdo da versão anterior do servidor)\nfunction downloadPdf(contract) {\n  if (!window.jspdf) { alert('Não foi possível gerar o PDF. Recarregue a página.'); return; }\n  const doc = new window.jspdf.jsPDF({ unit: 'pt', format: 'a4' });\n  const margin = 56;\n  const width = doc.internal.pageSize.getWidth() - margin * 2;\n  const bottom = doc.internal.pageSize.getHeight() - margin;\n  let y = margin;\n\n  function write(text, { size = 11, bold = false, color = 20, gap = 4, indent = 0 } = {}) {\n    doc.setFont('helvetica', bold ? 'bold' : 'normal');\n    doc.setFontSize(size);\n    doc.setTextColor(color);\n    const lines = doc.splitTextToSize(String(text), width - indent);\n    for (const line of lines) {\n      if (y + size > bottom) { doc.addPage(); y = margin; }\n      doc.text(line, margin + indent, y + size);\n      y += size + gap;\n    }\n  }\n\n  write(contract.title, { size: 20, bold: true, gap: 8 });\n  y += 8;\n  if (contract.body) { write(contract.body, { size: 11, color: 40, gap: 5 }); y += 12; }\n  if (contract.events.length) {\n    write('Eventos contratados', { size: 14, bold: true, gap: 8 });\n    for (const ev of contract.events) {\n      write(`${ev.title}${ev.event_date ? '  —  ' + ev.event_date : ''}`, { size: 12, bold: true });\n      for (const item of ev.items) write(`•  ${item}`, { size: 11, color: 60, indent: 14 });\n      y += 8;\n    }\n  }\n  y += 14;\n  write('Assinatura', { size: 13, bold: true, gap: 8 });\n  if (contract.status === 'signed') {\n    try {\n      if (y + 70 > bottom) { doc.addPage(); y = margin; }\n      doc.addImage(contract.signature_data_url, 'PNG', margin, y, 180, 60);\n      y += 70;\n    } catch { /* segue sem a imagem */ }\n    write(`Assinado por: ${contract.signer_name}`);\n    write(`Data: ${new Date(contract.signed_at).toLocaleString('pt-BR')}`);\n  } else {\n    write('Contrato ainda não assinado.', { color: 130 });\n  }\n  doc.save(`${contract.title.replace(/[^\\w\\-]+/g, '_')}.pdf`);\n}\n\nfunction setupSignaturePad() {\n  const canvas = el('signaturePad');\n  const ctx = canvas.getContext('2d');\n  const ratio = window.devicePixelRatio || 1;\n  canvas.width = canvas.offsetWidth * ratio;\n  canvas.height = canvas.offsetHeight * ratio;\n  ctx.scale(ratio, ratio);\n  ctx.strokeStyle = '#0d1420';\n  ctx.lineWidth = 2.2;\n  ctx.lineCap = 'round';\n  signaturePad = { canvas, ctx };\n\n  function pos(e) {\n    const rect = canvas.getBoundingClientRect();\n    const point = e.touches ? e.touches[0] : e;\n    return { x: point.clientX - rect.left, y: point.clientY - rect.top };\n  }\n\n  function start(e) {\n    e.preventDefault();\n    isDrawing = true;\n    hasSignature = true;\n    const p = pos(e);\n    ctx.beginPath();\n    ctx.moveTo(p.x, p.y);\n  }\n  function move(e) {\n    if (!isDrawing) return;\n    e.preventDefault();\n    const p = pos(e);\n    ctx.lineTo(p.x, p.y);\n    ctx.stroke();\n  }\n  function end() { isDrawing = false; }\n\n  canvas.addEventListener('mousedown', start);\n  canvas.addEventListener('mousemove', move);\n  window.addEventListener('mouseup', end);\n  canvas.addEventListener('touchstart', start, { passive: false });\n  canvas.addEventListener('touchmove', move, { passive: false });\n  canvas.addEventListener('touchend', end);\n\n  el('clearSignatureBtn').addEventListener('click', () => {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    hasSignature = false;\n  });\n\n  el('signBtn').addEventListener('click', async () => {\n    const name = el('signerName').value.trim();\n    if (!name) { alert('Digite seu nome completo.'); return; }\n    if (!hasSignature) { alert('Faça sua assinatura no campo acima.'); return; }\n\n    const signBtn = el('signBtn');\n    signBtn.disabled = true;\n    signBtn.textContent = 'Assinando...';\n\n    const signatureDataUrl = canvas.toDataURL('image/png');\n    const res = await fetch(`api/contracts/${currentContract.id}/sign`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ signerName: name, signatureDataUrl })\n    });\n    const data = await res.json();\n    if (!res.ok) {\n      alert(data.error || 'Erro ao assinar');\n      signBtn.disabled = false;\n      signBtn.textContent = 'Assinar contrato';\n      return;\n    }\n    loadContract();\n  });\n}\n\nloadContract();\n","etag":"\"0b2913dfbed55675\""},"js/convidados.js":{"body":"(async () => {\n  const params = new URLSearchParams(window.location.search);\n  const token = params.get('t');\n  const content = document.getElementById('content');\n  if (!token) { content.innerHTML = '<p style=\"text-align:center;\">Link inválido.</p>'; return; }\n\n  const res = await fetch(`api/albums/guest-upload/${token}`);\n  if (!res.ok) { content.innerHTML = '<p style=\"text-align:center;\">Este link de envio não está mais ativo.</p>'; return; }\n  const album = await res.json();\n\n  content.innerHTML = `\n    <h2 style=\"font-size:18px; text-align:center; margin-bottom:6px;\">${album.title}</h2>\n    <p style=\"text-align:center; color:var(--ink-dim); font-size:13px; margin-bottom:20px;\">Compartilhe suas fotos e vídeos do casamento com os noivos!</p>\n    <div class=\"field\"><label>Seu nome</label><input type=\"text\" id=\"uploaderName\" placeholder=\"Como quer aparecer\"></div>\n    <div class=\"file-field\" id=\"dropZone\">Toque aqui pra escolher suas fotos</div>\n    <input type=\"file\" id=\"fileInput\" accept=\"image/*\" multiple style=\"display:none;\">\n    <button class=\"btn btn-primary\" id=\"sendBtn\" style=\"width:100%; justify-content:center; margin-top:14px;\">Enviar fotos</button>\n    <p id=\"status\" style=\"text-align:center; font-size:13px; color:var(--gold); margin-top:12px;\"></p>\n  `;\n\n  const dropZone = document.getElementById('dropZone');\n  const fileInput = document.getElementById('fileInput');\n  let selectedFiles = [];\n\n  dropZone.addEventListener('click', () => fileInput.click());\n  fileInput.addEventListener('change', () => {\n    selectedFiles = Array.from(fileInput.files);\n    dropZone.textContent = `${selectedFiles.length} foto(s) selecionada(s)`;\n    dropZone.classList.add('has-file');\n  });\n\n  document.getElementById('sendBtn').addEventListener('click', async () => {\n    if (!selectedFiles.length) { alert('Escolha ao menos uma foto.'); return; }\n    const name = document.getElementById('uploaderName').value.trim() || 'Convidado';\n    const btn = document.getElementById('sendBtn');\n    const status = document.getElementById('status');\n    btn.disabled = true;\n    const result = await window.studioUploadPhotos(`api/albums/guest-upload/${encodeURIComponent(token)}/files`, selectedFiles, { uploader: name },\n      (done, total) => { btn.textContent = `Enviando ${done} de ${total}...`; });\n    const sent = result.done - result.failed;\n    if (sent > 0) {\n      status.textContent = result.failed\n        ? `Obrigado! ${sent} foto(s) chegaram ao álbum. ${result.failed} não foram enviadas: ${result.errors[0]}`\n        : `Obrigado! Suas ${sent} foto(s) já estão no álbum dos noivos. 🎉`;\n      btn.textContent = 'Enviado!';\n    } else {\n      alert(result.errors[0] || 'Não foi possível enviar as fotos');\n      btn.disabled = false;\n      btn.textContent = 'Enviar fotos';\n    }\n  });\n})();\n","etag":"\"79b14f08166c1039\""},"js/pacotes.js":{"body":"function formatBRL(value) {\n  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });\n}\n\nfunction packageCardHTML(pkg) {\n  const itemsListHTML = pkg.items.map(item => `\n    <li class=\"${item.default_included ? 'included' : ''}\">\n      <span>${item.default_included ? '✓' : '＋'} ${item.label}</span>\n      ${item.price > 0 ? `<span class=\"item-price\">${item.default_included ? 'incluso' : '+' + formatBRL(item.price)}</span>` : ''}\n    </li>\n  `).join('');\n\n  const customizeItemsHTML = pkg.items.map(item => `\n    <label class=\"customize-item\">\n      <input type=\"checkbox\" data-pkg=\"${pkg.id}\" data-item=\"${item.id}\" data-price=\"${item.price}\" ${item.default_included ? 'checked' : ''}>\n      <span class=\"label\">${item.label}</span>\n      <span class=\"price\">${formatBRL(item.price)}</span>\n    </label>\n  `).join('');\n\n  return `\n    <div class=\"package-card\" data-package-id=\"${pkg.id}\">\n      <h2>${pkg.title}</h2>\n      <p class=\"desc\">${pkg.description || ''}</p>\n      <div class=\"package-price\">${formatBRL(pkg.basePrice)} <span>pacote padrão</span></div>\n      <ul class=\"package-items-list\">${itemsListHTML}</ul>\n\n      <div class=\"customize-panel\" id=\"customize-${pkg.id}\">\n        <p style=\"font-size:12.5px; color:var(--ink-dim); margin-bottom:8px;\">Marque ou desmarque os itens pra montar seu pacote:</p>\n        ${customizeItemsHTML}\n        <div class=\"package-total\">Total: <span id=\"total-${pkg.id}\">${formatBRL(pkg.basePrice)}</span></div>\n      </div>\n\n      <div class=\"checkout-form\" id=\"checkoutForm-${pkg.id}\">\n        <div class=\"field\"><label>Seu nome</label><input type=\"text\" id=\"payerName-${pkg.id}\" placeholder=\"Nome completo\"></div>\n        <div class=\"field\"><label>Seu e-mail</label><input type=\"email\" id=\"payerEmail-${pkg.id}\" placeholder=\"voce@email.com\" required></div>\n        <button class=\"btn btn-primary\" style=\"width:100%; justify-content:center;\" onclick=\"goToPayment(${pkg.id})\">Ir para o pagamento →</button>\n      </div>\n\n      <div class=\"package-actions\">\n        <button class=\"btn btn-primary\" onclick=\"startCheckout(${pkg.id}, true)\">Contratar agora</button>\n        <button class=\"btn btn-ghost\" onclick=\"toggleCustomize(${pkg.id})\">Personalizar itens</button>\n      </div>\n    </div>\n  `;\n}\n\nasync function loadPackages() {\n  const res = await fetch('api/packages');\n  const grid = document.getElementById('packagesGrid');\n  if (!res.ok) { grid.innerHTML = `<p style=\"color:var(--ink-dim); padding:0 40px;\">Erro ao carregar pacotes.</p>`; return; }\n  const packages = await res.json();\n\n  if (!packages.length) {\n    grid.innerHTML = `<div class=\"empty-state\" style=\"grid-column:1/-1;\"><h2>Nenhum pacote disponível ainda</h2><p>Em breve os pacotes de serviço aparecem aqui.</p></div>`;\n    return;\n  }\n\n  grid.innerHTML = packages.map(packageCardHTML).join('');\n\n  // Recalcula o total ao vivo conforme o cliente marca/desmarca itens\n  grid.querySelectorAll('.customize-item input').forEach(input => {\n    input.addEventListener('change', () => {\n      const pkgId = input.dataset.pkg;\n      const checkboxes = grid.querySelectorAll(`.customize-item input[data-pkg=\"${pkgId}\"]`);\n      let total = 0;\n      checkboxes.forEach(cb => { if (cb.checked) total += Number(cb.dataset.price); });\n      document.getElementById(`total-${pkgId}`).textContent = formatBRL(total);\n    });\n  });\n}\n\nwindow.toggleCustomize = (pkgId) => {\n  document.getElementById(`customize-${pkgId}`).classList.toggle('open');\n};\n\nwindow.startCheckout = (pkgId, useDefault) => {\n  document.getElementById(`checkoutForm-${pkgId}`).classList.add('open');\n  document.getElementById(`checkoutForm-${pkgId}`).scrollIntoView({ behavior: 'smooth', block: 'center' });\n};\n\nwindow.goToPayment = async (pkgId) => {\n  const name = document.getElementById(`payerName-${pkgId}`).value.trim();\n  const email = document.getElementById(`payerEmail-${pkgId}`).value.trim();\n  if (!email) { alert('Digite seu e-mail pra continuar.'); return; }\n\n  const card = document.querySelector(`.package-card[data-package-id=\"${pkgId}\"]`);\n  const customizeOpen = document.getElementById(`customize-${pkgId}`).classList.contains('open');\n  let selectedItemIds = null;\n  if (customizeOpen) {\n    selectedItemIds = Array.from(card.querySelectorAll('.customize-item input:checked')).map(cb => Number(cb.dataset.item));\n  }\n\n  const btn = event.target;\n  btn.disabled = true;\n  btn.textContent = 'Redirecionando...';\n\n  try {\n    const res = await fetch(`api/packages/${pkgId}/checkout`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ selectedItemIds, payerName: name, payerEmail: email })\n    });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error || 'Erro ao iniciar pagamento');\n    window.location.href = data.checkoutUrl;\n  } catch (err) {\n    alert(err.message);\n    btn.disabled = false;\n    btn.textContent = 'Ir para o pagamento →';\n  }\n};\n\n(async () => {\n  const user = await trySession();\n  document.getElementById('myAreaLink').style.display = user ? 'block' : 'none';\n  loadPackages();\n})();\n","etag":"\"1e47a4fcddc407bf\""},"js/portfolio.js":{"body":"function formatDuration(seconds) {\n  if (!seconds) return '';\n  const h = Math.floor(seconds / 3600);\n  const m = Math.round((seconds % 3600) / 60);\n  return h > 0 ? `${h}h ${m}min` : `${m}min`;\n}\n\n// ---------- Hero rotativo (mesmo comportamento da área privada) ----------\nlet heroReels = [];\nlet heroIndex = 0;\n\nfunction heroMarkup(video) {\n  return `\n    <section class=\"hero\">\n      <video class=\"hero-bg\" id=\"heroVideo\" muted autoplay playsinline></video>\n      <div class=\"hero-content\">\n        <div class=\"category\">${video.category}</div>\n        <h1 id=\"heroTitle\">${video.title}</h1>\n        <p id=\"heroDesc\">${video.description || ''}</p>\n        <a class=\"btn btn-primary\" id=\"heroCta\" href=\"watch.html?id=${video.id}\">▶ Assistir</a>\n      </div>\n      <div class=\"hero-dots\" id=\"heroDots\"></div>\n    </section>\n  `;\n}\n\nfunction renderHeroDots() {\n  const dots = document.getElementById('heroDots');\n  if (!dots || heroReels.length < 2) { if (dots) dots.innerHTML = ''; return; }\n  dots.innerHTML = heroReels.map((_, i) =>\n    `<button class=\"${i === heroIndex ? 'active' : ''}\" onclick=\"window.__heroGoTo(${i})\"></button>`\n  ).join('');\n}\n\nfunction loadHeroVideo(index) {\n  heroIndex = index;\n  const video = heroReels[heroIndex];\n  const videoEl = document.getElementById('heroVideo');\n  document.getElementById('heroTitle').textContent = video.title;\n  document.getElementById('heroDesc').textContent = video.description || '';\n  document.getElementById('heroCta').href = `watch.html?id=${video.id}`;\n  renderHeroDots();\n\n  videoEl.src = video.video_url;\n  videoEl.play().catch(() => {});\n}\n\nwindow.__heroGoTo = (i) => loadHeroVideo(i);\nfunction advanceHero() { loadHeroVideo((heroIndex + 1) % heroReels.length); }\n\nfunction renderHero(reelVideos, fallback) {\n  const section = document.getElementById('heroSection');\n  if (!reelVideos.length) {\n    if (!fallback) { section.innerHTML = ''; return; }\n    section.innerHTML = `\n      <section class=\"hero\" style=\"background-image:url('${fallback.poster_url || fallback.cover_url || ''}'); background-size:cover; background-position:center;\">\n        <div class=\"hero-content\">\n          <div class=\"category\">${fallback.category}</div>\n          <h1>${fallback.title}</h1>\n          <p>${fallback.description || ''}</p>\n        </div>\n      </section>\n    `;\n    return;\n  }\n  heroReels = reelVideos;\n  section.innerHTML = heroMarkup(reelVideos[0]);\n  document.getElementById('heroVideo').addEventListener('ended', advanceHero);\n  loadHeroVideo(0);\n}\n\n// ---------- Cards ----------\nfunction videoCardHTML(video) {\n  return `\n    <a class=\"card\" href=\"watch.html?id=${video.id}\">\n      <div class=\"card-thumb\" style=\"background-image:url('${video.poster_url || ''}')\">\n        ${video.max_quality ? `<span class=\"badge\">${video.max_quality}</span>` : ''}\n      </div>\n      <div class=\"card-title\">${video.title}</div>\n      <div class=\"card-meta\">${formatDuration(video.duration_seconds)}</div>\n    </a>\n  `;\n}\n\nfunction albumCardHTML(album) {\n  return `\n    <a class=\"card\" href=\"album.html?id=${album.id}\">\n      <div class=\"card-thumb\" style=\"background-image:url('${album.cover_url || ''}')\">\n        <span class=\"badge\">📷 Álbum</span>\n      </div>\n      <div class=\"card-title\">${album.title}</div>\n    </a>\n  `;\n}\n\nasync function loadPortfolio() {\n  const [videosRes, albumsRes, testimonialsRes] = await Promise.all([\n    fetch('api/videos/portfolio'),\n    fetch('api/albums/portfolio'),\n    fetch('api/testimonials/portfolio')\n  ]);\n  const videos = videosRes.ok ? await videosRes.json() : [];\n  const albums = albumsRes.ok ? await albumsRes.json() : [];\n  const testimonials = testimonialsRes.ok ? await testimonialsRes.json() : [];\n  const rowsEl = document.getElementById('rows');\n\n  const reels = videos.filter(v => v.orientation === 'vertical' && v.status === 'ready');\n  const films = videos.filter(v => v.orientation !== 'vertical' && v.status === 'ready');\n\n  renderHero(reels, films[0] || albums[0]);\n\n  if (!films.length && !albums.length) {\n    rowsEl.innerHTML = reels.length ? '' : `<div class=\"empty-state\">\n      <h2>Portfólio em construção</h2>\n      <p>Assim que os primeiros filmes e álbuns forem publicados, eles aparecem aqui.</p>\n    </div>`;\n    return;\n  }\n\n  let html = '';\n\n  if (films.length) {\n    const byCategory = {};\n    for (const v of films) { (byCategory[v.category] ||= []).push(v); }\n    html += Object.entries(byCategory).map(([cat, list]) => `\n      <div class=\"row\">\n        <div class=\"row-header\"><h2>${cat}</h2></div>\n        <div class=\"row-track\">${list.map(videoCardHTML).join('')}</div>\n      </div>\n    `).join('');\n  }\n\n  if (albums.length) {\n    html += `\n      <div class=\"row\">\n        <div class=\"row-header\"><h2>Álbuns de fotos</h2></div>\n        <div class=\"albums-grid\">${albums.map(albumCardHTML).join('')}</div>\n      </div>\n    `;\n  }\n\n  if (testimonials.length) {\n    html += `\n      <div class=\"row\">\n        <div class=\"row-header\"><h2>O que os casais dizem</h2></div>\n        <div class=\"row-track\">\n          ${testimonials.map(t => `\n            <div class=\"card\" style=\"width:280px;\">\n              <div class=\"card-thumb\" style=\"background-image:url('${t.photo_url || ''}'); ${t.photo_url ? '' : 'background:var(--surface);'}\"></div>\n              <p style=\"font-size:13px; color:var(--ink-dim); margin-top:10px; line-height:1.5; font-style:italic;\">\"${t.quote}\"</p>\n              <div class=\"card-title\" style=\"margin-top:6px;\">— ${t.client_name}</div>\n            </div>\n          `).join('')}\n        </div>\n      </div>\n    `;\n  }\n\n  rowsEl.innerHTML = html;\n}\n\n(async () => {\n  const user = await trySession();\n  document.getElementById('loginLink').style.display = user ? 'none' : 'inline';\n  document.getElementById('myAreaLink').style.display = user ? 'inline' : 'none';\n  loadPortfolio();\n})();\n","etag":"\"7ca8122f75a74ae6\""},"js/studio.js":{"body":"// Base comum de todas as páginas do DunaStudio:\n// - conecta no Supabase (login) com a configuração que o Worker entrega em api/config\n// - coloca o token de login em toda chamada para api/... (o Worker confere quem é o usuário)\n// - funções de envio de fotos (com miniatura gerada no navegador)\n(function () {\n  'use strict';\n\n  const nativeFetch = window.fetch.bind(window);\n  let client = null;\n\n  window.studioReady = (async () => {\n    try {\n      const res = await nativeFetch('api/config', { cache: 'no-store' });\n      const cfg = await res.json();\n      if (window.supabase && cfg.supabaseUrl && cfg.supabaseAnonKey) {\n        client = window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseAnonKey, {\n          auth: { persistSession: true, autoRefreshToken: true, storageKey: 'dunastudio-auth' }\n        });\n      }\n    } catch (err) {\n      console.error('[studio] Falha ao carregar a configuração', err);\n    }\n    return client;\n  })();\n\n  window.studioClient = () => window.studioReady;\n\n  async function accessToken() {\n    const c = await window.studioReady;\n    if (!c) return null;\n    const { data } = await c.auth.getSession();\n    return data?.session?.access_token || null;\n  }\n  window.studioAccessToken = accessToken;\n\n  function isApiCall(input) {\n    const raw = typeof input === 'string' ? input : input && input.url;\n    if (!raw) return false;\n    const url = new URL(raw, window.location.href);\n    return url.origin === window.location.origin && url.pathname.includes('/api/') && !url.pathname.includes('/api/media/');\n  }\n\n  window.fetch = async function (input, init = {}) {\n    if (!isApiCall(input)) return nativeFetch(input, init);\n    const token = await accessToken();\n    const headers = new Headers(init.headers || (typeof input !== 'string' ? input.headers : undefined));\n    if (token && !headers.has('Authorization')) headers.set('Authorization', `Bearer ${token}`);\n    return nativeFetch(input, { ...init, headers });\n  };\n\n  // ---------- Fotos: miniatura no navegador + envio em duas etapas ----------\n  async function makeThumbnail(file, maxSide = 900) {\n    let source;\n    try {\n      source = await createImageBitmap(file);\n    } catch {\n      source = await new Promise((resolve, reject) => {\n        const img = new Image();\n        img.onload = () => resolve(img);\n        img.onerror = reject;\n        img.src = URL.createObjectURL(file);\n      });\n    }\n    const w = source.width, h = source.height;\n    const scale = Math.min(1, maxSide / Math.max(w, h));\n    const canvas = document.createElement('canvas');\n    canvas.width = Math.max(1, Math.round(w * scale));\n    canvas.height = Math.max(1, Math.round(h * scale));\n    canvas.getContext('2d').drawImage(source, 0, 0, canvas.width, canvas.height);\n    return new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.82));\n  }\n\n  // baseUrl: \"api/albums/12/files\" (admin) ou \"api/albums/guest-upload/TOKEN/files\" (convidados)\n  async function uploadPhoto(baseUrl, file, extraParams = {}) {\n    const thumb = await makeThumbnail(file);\n    const params = new URLSearchParams({ ...extraParams, name: file.name || 'foto.jpg' });\n\n    const photoRes = await fetch(`${baseUrl}?kind=photo&${params}`, {\n      method: 'PUT', headers: { 'Content-Type': file.type || 'image/jpeg' }, body: file\n    });\n    const photoData = await photoRes.json().catch(() => ({}));\n    if (!photoRes.ok) throw new Error(photoData.error || `Falha ao enviar ${file.name}`);\n\n    params.set('for', photoData.key);\n    const thumbRes = await fetch(`${baseUrl}?kind=thumb&${params}`, {\n      method: 'PUT', headers: { 'Content-Type': 'image/jpeg' }, body: thumb\n    });\n    const thumbData = await thumbRes.json().catch(() => ({}));\n    if (!thumbRes.ok) throw new Error(thumbData.error || `Falha ao registrar ${file.name}`);\n    return thumbData;\n  }\n\n  // Envia várias fotos, 3 de cada vez. onProgress(enviadas, total, falhas)\n  window.studioUploadPhotos = async function (baseUrl, files, extraParams, onProgress) {\n    const list = Array.from(files);\n    let done = 0, failed = 0, next = 0;\n    const errors = [];\n    async function worker() {\n      while (next < list.length) {\n        const file = list[next++];\n        try { await uploadPhoto(baseUrl, file, extraParams); }\n        catch (err) { failed++; errors.push(err.message); }\n        done++;\n        if (onProgress) onProgress(done, list.length, failed);\n      }\n    }\n    await Promise.all([worker(), worker(), worker()]);\n    return { done, failed, errors };\n  };\n})();\n","etag":"\"f177e41f6d7f7d62\""},"js/watch.js":{"body":"(async () => {\n  const user = await trySession();\n  document.querySelector('.back').href = user ? 'index.html' : './';\n\n  const params = new URLSearchParams(window.location.search);\n  const videoId = params.get('id');\n  if (!videoId) { window.location.href = './'; return; }\n\n  const res = await fetch(`api/videos/${videoId}`);\n  if (res.status === 403) {\n    document.querySelector('.watch-wrap').innerHTML = `\n      <div class=\"watch-info\" style=\"padding-top:80px; max-width:480px; margin:0 auto; text-align:center;\">\n        <h2>Este vídeo é privado</h2>\n        <p style=\"margin-bottom:20px;\">Faça login com a conta do cliente pra assistir.</p>\n        <a class=\"btn btn-primary\" href=\"login.html\">Entrar</a>\n      </div>`;\n    return;\n  }\n  if (!res.ok) { window.location.href = './'; return; }\n  const video = await res.json();\n\n  document.getElementById('videoTitleTop').textContent = video.title;\n  document.getElementById('videoTitle').textContent = video.title;\n  document.getElementById('videoDescription').textContent = video.description || '';\n\n  if (video.max_quality) {\n    const tag = document.getElementById('qualityTag');\n    tag.textContent = `Qualidade máxima: ${video.max_quality}`;\n    tag.style.display = 'inline-block';\n  }\n\n  if (video.orientation === 'vertical') {\n    document.querySelector('.watch-wrap').classList.add('is-vertical');\n  }\n\n  const videoEl = document.getElementById('player');\n  const progressKey = 'wf_progress_' + video.id;\n\n  if (video.status !== 'ready') {\n    document.querySelector('.watch-info').insertAdjacentHTML('beforeend',\n      `<p style=\"color:var(--gold); margin-top:12px;\">Este vídeo ainda está sendo processado. Volte em alguns minutos.</p>`);\n    return;\n  }\n\n  function restoreProgress() {\n    try {\n      const raw = localStorage.getItem(progressKey);\n      if (!raw) return;\n      const { time } = JSON.parse(raw);\n      if (time && time > 5) videoEl.currentTime = time;\n    } catch {}\n  }\n\n  function saveProgress() {\n    if (!videoEl.duration) return;\n    const pct = Math.round((videoEl.currentTime / videoEl.duration) * 100);\n    localStorage.setItem(progressKey, JSON.stringify({ time: videoEl.currentTime, pct }));\n  }\n\n  videoEl.addEventListener('timeupdate', () => {\n    // salva a cada ~5s de reprodução, não a cada frame\n    if (Math.floor(videoEl.currentTime) % 5 === 0) saveProgress();\n  });\n  videoEl.addEventListener('pause', saveProgress);\n  window.addEventListener('beforeunload', saveProgress);\n\n  // Os filmes são MP4 servidos direto do R2 (o navegador busca por partes conforme a reprodução)\n  videoEl.src = video.video_url;\n  videoEl.addEventListener('loadedmetadata', restoreProgress, { once: true });\n  videoEl.addEventListener('error', () => {\n    document.querySelector('.watch-info').insertAdjacentHTML('beforeend',\n      `<p style=\"color:var(--danger); margin-top:12px;\">Não foi possível carregar o filme. Recarregue a página e tente de novo.</p>`);\n  }, { once: true });\n})();\n","etag":"\"caa95a042c7822a3\""}};
